// Der Aufrufer uebergibt doc_id als DEFINIERTE Eingabe (siehe Trigger),
// nicht als beliebigen Datenstrom ('passthrough'). Sonst haengt es davon
// ab, was zufaellig im Strom liegt, und ein Umbau im Aufrufer bricht
// den Sub.
//
// Die Fallbacks bleiben fuer den Handtest im Editor: dort kann man ein
// Item mit doc_url oder id pinnen.
const inp = $('Aufruf').first().json ?? {};
const src = inp.body ?? inp;
let id = src.doc_id ?? src.id;
if (!id && src.doc_url) {
  id = String(src.doc_url).match(/\/documents\/(\d+)/)?.[1];
}
if (!id) throw new Error('Keine doc_id im Aufruf. Erwartet wird die Eingabe doc_id (Zahl).');
return [{ json: { id: Number(id) } }];

// Datei als Base64-Data-URL fuer Mistral OCR aufbereiten.
// PDFs -> document_url, Bilder -> image_url (Mistral akzeptiert beides als Base64).
const id = $('Extract ID').first().json.id;
const binaryKey = Object.keys($input.first().binary ?? {})[0];
if (!binaryKey) throw new Error('Kein Binary vom Download erhalten');
const meta = $input.first().binary[binaryKey];
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const mime = meta.mimeType || 'application/octet-stream';
const isPdf = mime === 'application/pdf' || (meta.fileName || '').toLowerCase().endsWith('.pdf');
const dataUrl = `data:${mime};base64,${buffer.toString('base64')}`;
const document = isPdf
  ? { type: 'document_url', document_url: dataUrl }
  : { type: 'image_url', image_url: dataUrl };
return [{ json: { id, mistralOcrBody: { model: 'mistral-ocr-latest', document } } }];

// Markdown aller Seiten zu einem Text zusammenfuegen.
const id = $('Extract ID').first().json.id;
const pages = $json.pages ?? [];
const content = pages.map((p) => (p.markdown || '').trim()).filter(Boolean).join('\n\n');
if (!content) throw new Error('Mistral OCR lieferte keinen Text: ' + JSON.stringify($json).slice(0, 300));
return [{ json: { id, content, pages_processed: pages.length } }];

// Titel-Prompt aus dem neuen OCR-content bauen (wie create-title-mistral).
const doc = $('Extract text').first().json;

const SYSTEM_PROMPT = `Du bist ein Assistent zur Verbesserung von Dokumenttiteln in einem Paperless-Dokumentenmanagementsystem. Aus dem OCR-Volltext eines Dokuments und seinem aktuellen Titel erzeugst du einen prägnanten, sprechenden neuen Titel.

Regeln für den neuen Titel:
- 1 bis 5 Wörter, idealerweise unter 40 Zeichen
- Sprache: passend zum Dokumentinhalt (in der Regel Deutsch)
- Enthält das Wesentliche in dieser Reihenfolge: Absender/Korrespondent · Vorgang/Thema · ggf. eindeutige Referenz (Rechnungs-Nr., Aktenzeichen, Vertragsnummer); ein Datum nur, wenn es für die Wiederfindbarkeit unverzichtbar ist
- Keine Anführungszeichen, kein Punkt am Ende, keine Dateiendung, keine Aufzählungszeichen
- Keine generischen Wörter wie „Dokument", „Schreiben", „PDF", „Scan"
- Eigennamen, Firmen- und Produktnamen exakt übernehmen (auch Groß-/Kleinschreibung)
- Wenn der aktuelle Titel bereits gut beschreibend und prägnant ist, gib ihn unverändert zurück
- Bei unklarem Inhalt: gib den besten möglichen Versuch ab; verweigere nicht und entschuldige dich nicht

Antworte ausschließlich mit gültigem JSON in genau diesem Format und ohne weitere Felder:
{"new_title": "..."}`;

const contentExcerpt = (doc.content ?? '').slice(0, 6000);

const userContent = `Aktueller Titel: (leer)

OCR-Volltext (Auszug, ggf. gekürzt):
---
${contentExcerpt}
---

Erzeuge nun den neuen Titel und antworte als JSON.`;

return [{
  json: {
    id: doc.id,
    mistralBody: {
      model: 'mistral-small-latest',
      response_format: { type: 'json_object' },
      temperature: 0.2,
      max_tokens: 200,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: userContent },
      ],
    },
  },
}];

function extractNewTitle(raw) {
  if (raw == null) return null;

  if (typeof raw === 'string') {
    const s = raw.trim();
    if (s === '') return null;
    try {
      const parsed = JSON.parse(s);
      return extractNewTitle(parsed);
    } catch {
      return s;
    }
  }

  if (typeof raw !== 'object') return null;

  if (typeof raw.new_title === 'string' && raw.new_title.trim() !== '') {
    return raw.new_title.trim();
  }

  if (raw.message && typeof raw.message === 'object') {
    const t = extractNewTitle(raw.message.content);
    if (t) return t;
  }

  if (Array.isArray(raw.choices) && raw.choices.length > 0) {
    for (const c of raw.choices) {
      const t = extractNewTitle(c?.message?.content);
      if (t) return t;
    }
  }

  if (typeof raw.content === 'string') {
    const t = extractNewTitle(raw.content);
    if (t) return t;
  }

  return null;
}

const src = $('Extract text').first().json;
const aiItem = $input.first().json;
let title = extractNewTitle(aiItem);

if (!title) {
  throw new Error('Konnte keinen new_title aus Mistral-Antwort extrahieren: ' + JSON.stringify(aiItem).slice(0, 500));
}

title = title
  .replace(/[\r\n\t]+/g, ' ')
  .replace(/\s{2,}/g, ' ')
  .replace(/^["']|["']$/g, '')
  .replace(/\.$/g, '')
  .trim();

if (title.length > 200) title = title.slice(0, 200).trim();

return [{ json: { id: src.id, content: src.content, title } }];

// Ergebnis an den aufrufenden Protokoll-Workflow. Bewusst ohne jeden
